    vts.forEach(function (v) { add('vt:' + v.id, v, agora - DIA); });

    /* Fotos dos pontos por campanha (registro das fotos feitas pelos motoboys) */
    function foto(vt, pid, status, moto, horasAtras, extra) {
      var d = { moto: moto, ts: agora - horasAtras * HORA, status: status, nota: '' };
      if (extra) Object.keys(extra).forEach(function (k) { d[k] = extra[k]; });
      add('ft:' + vt + '__' + pid, d, agora - horasAtras * HORA);
    }
    foto('v1001', 'p1', 'validada', 'Thiago', 50);
